#!/usr/bin/env bash
set -euo pipefail

echo "[MEMEFLOW] Installing FINAL Dragonfly Brand Pack v5"

ROOT="$(pwd)"
if [ -d "$ROOT/memeflow-app" ]; then
  APP="$ROOT/memeflow-app"
elif [ "$(basename "$ROOT")" = "memeflow-app" ]; then
  APP="$ROOT"
  ROOT="$(dirname "$ROOT")"
else
  echo "ERROR: memeflow-app not found. Run this from ~/workspace or ~/workspace/memeflow-app"
  exit 1
fi

export APP
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="$ROOT/.memeflow-brand-backup-$STAMP"
mkdir -p "$BACKUP"
for f in index.html trading.html trading.css system.html system.css system-tokens.html system-tokens.css memeflow-brand.css; do
  [ -f "$APP/$f" ] && cp -p "$APP/$f" "$BACKUP/$f"
done
mkdir -p "$APP/brand"
echo "[MEMEFLOW] Backup: $BACKUP"

base64 -d > "$APP/brand/memeflow-dragonfly-master.png" <<'MF_2477BD57'

MF_2477BD57

base64 -d > "$APP/brand/memeflow-dragonfly-dark.png" <<'MF_8ED1297F'

MF_8ED1297F

base64 -d > "$APP/brand/memeflow-dragonfly-light.png" <<'MF_5CE057F3'

MF_5CE057F3

base64 -d > "$APP/brand/memeflow-dragonfly.webp" <<'MF_78BEDDBB'

MF_78BEDDBB

base64 -d > "$APP/brand/favicon.ico" <<'MF_8AF3A74E'

MF_8AF3A74E

base64 -d > "$APP/brand/memeflow-dragonfly-loader.gif" <<'MF_B104C828'

MF_B104C828

base64 -d > "$APP/brand/layer-body.png" <<'MF_E25E66D5'

MF_E25E66D5

base64 -d > "$APP/brand/layer-wings-left.png" <<'MF_623140EC'

MF_623140EC

base64 -d > "$APP/brand/layer-wings-right.png" <<'MF_3AAB359B'

MF_3AAB359B

