MF_5DE78EFD

cat > "$APP/memeflow-brand.css" <<'MFCSS'
/* MEMEFLOW BRAND FINAL V5 — single canonical layer
   One master geometry everywhere. Dark/light differ only in color processing.
*/
:root{
  --mf-logo-dark:url("/brand/memeflow-dragonfly-dark.png?v=final-v5");
  --mf-logo-light:url("/brand/memeflow-dragonfly-light.png?v=final-v5");
}
.mf-brand-img{display:block;object-fit:contain;filter:drop-shadow(0 3px 8px rgba(0,229,240,.18));}
.logo{
  width:40px!important;height:40px!important;min-width:40px!important;flex:0 0 40px!important;
  display:inline-block!important;border:0!important;border-radius:0!important;box-shadow:none!important;
  background:var(--mf-logo-dark) center/contain no-repeat!important;
}
.logo::before,.logo::after{content:none!important;display:none!important;}
.brand-mark{
  width:58px!important;height:42px!important;min-width:58px!important;flex:0 0 58px!important;
  display:inline-flex!important;align-items:center!important;justify-content:center!important;
  padding:0!important;margin:0!important;border:0!important;border-radius:0!important;
  background:none!important;box-shadow:none!important;color:transparent!important;font-size:0!important;line-height:0!important;
}
.brand-mark>span,.brand-mark>i,.brand-mark::before,.brand-mark::after{display:none!important;content:none!important;}
.brand-mark .mf-brand-img{width:56px!important;height:38px!important;}
.boot-mark{
  width:104px!important;height:82px!important;min-width:104px!important;
  display:flex!important;align-items:center!important;justify-content:center!important;
  border:0!important;border-radius:0!important;background:none!important;box-shadow:none!important;overflow:visible!important;
}
.boot-mark>i,.boot-mark::before,.boot-mark::after{display:none!important;content:none!important;}
.mf-loader{
  position:relative;width:100px;height:76px;display:block;
  filter:drop-shadow(0 7px 18px rgba(0,229,240,.28));
}
.mf-loader img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;transform-origin:50% 44%;}
.mf-loader .mf-glow{animation:mfGlow 1.5s ease-in-out infinite;}
.mf-loader .mf-left{animation:mfWingL .7s ease-in-out infinite alternate;}
.mf-loader .mf-right{animation:mfWingR .7s ease-in-out infinite alternate;}
@keyframes mfWingL{from{transform:rotate(-1.8deg)}to{transform:rotate(1.8deg)}}
@keyframes mfWingR{from{transform:rotate(1.8deg)}to{transform:rotate(-1.8deg)}}
@keyframes mfGlow{from{opacity:.42;transform:scale(.97)}to{opacity:.78;transform:scale(1.035)}}
@media (prefers-reduced-motion:reduce){
  .mf-loader .mf-left,.mf-loader .mf-right,.mf-loader .mf-glow{animation:none!important}
}
html[data-theme="light"] .logo, body.light .logo, .theme-light .logo{background-image:var(--mf-logo-light)!important;}
html[data-theme="light"] .mf-brand-img, body.light .mf-brand-img, .theme-light .mf-brand-img{content:url("/brand/memeflow-dragonfly-light.png?v=final-v5");}
@media (prefers-color-scheme:light){
  html:not([data-theme="dark"]) .logo{background-image:var(--mf-logo-light)!important;}
}
@media(max-width:820px){
  .brand-mark{width:54px!important;height:40px!important;min-width:54px!important;flex-basis:54px!important;}
  .brand-mark .mf-brand-img{width:52px!important;height:36px!important;}
}

MFCSS

python3 <<'PY'
import os, re
from pathlib import Path
app = Path(os.environ["APP"])
dark = "/brand/memeflow-dragonfly-dark.png?v=final-v5"

# Remove all previous assistant branding layers/references.
for name in ("index.html","trading.html","system.html","system-tokens.html"):
    p = app / name
    if not p.exists():
        continue
    text = p.read_text(encoding="utf-8")
    text = re.sub(r'\s*<style id="memeflow-dragonfly-brand-v1">.*?</style>\s*', '\n', text, flags=re.S)
    text = re.sub(r'\s*<link[^>]+href=["\']/memeflow-brand\.css[^"\']*["\'][^>]*>\s*', '\n', text, flags=re.I)
    text = re.sub(r'/memeflow-dragonfly\.(?:png|svg)\?[^"\'\s>]+', dark, text)
    link = '<link rel="stylesheet" href="/memeflow-brand.css?v=final-v5">'
    if "</head>" in text:
        text = text.replace("</head>", link + "\n</head>", 1)
    p.write_text(text, encoding="utf-8")

for name in ("trading.css","system.css","system-tokens.css"):
    p = app / name
    if not p.exists():
        continue
    text = p.read_text(encoding="utf-8")
    marker = "/* MF_DRAGONFLY_GLOBAL_V2 */"
    if marker in text:
        text = text.split(marker,1)[0].rstrip() + "\n"
    p.write_text(text, encoding="utf-8")

# Trading header.
p = app / "trading.html"
if p.exists():
    t = p.read_text(encoding="utf-8")
    t = re.sub(
        r'<a\s+class="brand-mark"\s+href="/system\.html"\s+aria-label="Back to MEMEFLOW system"\s*>.*?</a>',
        '<a class="brand-mark" href="/system.html" aria-label="Back to MEMEFLOW system"><img class="mf-brand-img" src="/brand/memeflow-dragonfly-dark.png?v=final-v5" alt=""></a>',
        t, flags=re.S)
    p.write_text(t, encoding="utf-8")

# System header + layered PNG loader.
p = app / "system.html"
if p.exists():
    t = p.read_text(encoding="utf-8")
    t = re.sub(
        r'<div\s+class="brand-mark"[^>]*>.*?</div>',
        '<div class="brand-mark" aria-hidden="true"><img class="mf-brand-img" src="/brand/memeflow-dragonfly-dark.png?v=final-v5" alt=""></div>',
        t, count=1, flags=re.S)
    loader = (
      '<div class="boot-mark"><span class="mf-loader">'
      '<img class="mf-glow" src="/brand/layer-glow.png?v=final-v5" alt="">'
      '<img class="mf-left" src="/brand/layer-wings-left.png?v=final-v5" alt="">'
      '<img class="mf-right" src="/brand/layer-wings-right.png?v=final-v5" alt="">'
      '<img class="mf-body" src="/brand/layer-body.png?v=final-v5" alt="">'
      '</span></div>'
    )
    t = re.sub(r'<div\s+class="boot-mark"[^>]*>.*?</div>', loader, t, count=1, flags=re.S)
    p.write_text(t, encoding="utf-8")

# Token Flow header.
p = app / "system-tokens.html"
if p.exists():
    t = p.read_text(encoding="utf-8")
    t = re.sub(
        r'<div\s+class="brand-mark"[^>]*>.*?</div>',
        '<div class="brand-mark" aria-hidden="true"><img class="mf-brand-img" src="/brand/memeflow-dragonfly-dark.png?v=final-v5" alt=""></div>',
        t, count=1, flags=re.S)
    p.write_text(t, encoding="utf-8")
PY

# Remove obsolete experimental SVG so it cannot be picked up accidentally.
rm -f "$APP/memeflow-dragonfly.svg"

echo
echo "[MEMEFLOW] HTTP verification"
for u in \
  /brand/memeflow-dragonfly-dark.png \
  /brand/memeflow-dragonfly-light.png \
  /brand/favicon.ico \
  /brand/memeflow-dragonfly-loader.gif \
  /memeflow-brand.css \
  /system.html \
  /trading.html
do
  code="$(curl -s -o /dev/null -w '%{http_code}' "http://127.0.0.1:3000$u" || true)"
  echo "  $u -> $code"
done

echo
echo "✅ FINAL DRAGONFLY BRAND PACK V5 INSTALLED LOCALLY"
echo "Master geometry is identical across dark/light/favicon/loader."
echo "No commit/push was performed by this installer."
echo
echo "Preview:"
echo "  /brand/memeflow-dragonfly-dark.png?v=final-v5"
echo "  /brand/memeflow-dragonfly-light.png?v=final-v5"
echo "  /system.html?v=final-v5"
echo "  /trading.html?v=final-v5"
echo "  /system-tokens.html?v=final-v5"
